<script>
// Tiny demo cursor blink for typewriter card
(function(){
    const style = document.createElement('style');
    style.textContent = '.qcursor{display:inline-block;color:#fbbf24;animation:qbl .9s steps(2) infinite;margin-left:1px}@keyframes qbl{50%{opacity:0}}.quran-slide-demo{display:inline-block;animation:qslide 4s ease-in-out infinite}@keyframes qslide{0%,100%{transform:translateX(0)}45%{transform:translateX(0)}50%{transform:translateX(-30%);opacity:0}55%{transform:translateX(30%);opacity:0}60%,90%{transform:translateX(0);opacity:1}}';
    document.head.appendChild(style);
})();

// Highlight selected layout / preset
document.querySelectorAll('.layout-card').forEach(card => {
    card.addEventListener('click', () => {
        document.querySelectorAll('.layout-card').forEach(c => c.classList.remove('selected'));
        card.classList.add('selected');
        card.querySelector('input[type=radio]').checked = true;
    });
});
document.querySelectorAll('.preset-card').forEach(card => {
    card.addEventListener('click', () => {
        document.querySelectorAll('.preset-card').forEach(c => c.classList.remove('selected'));
        card.classList.add('selected');
        card.querySelector('input[type=radio]').checked = true;
    });
});

// Quran display mode cards (highlight on click)
document.querySelectorAll('input[name="quran_display"]').forEach(input => {
    input.addEventListener('change', () => {
        document.querySelectorAll('input[name="quran_display"]').forEach(i => {
            const lbl = i.closest('label');
            if (i.checked) {
                lbl.classList.remove('border-slate-200');
                lbl.classList.add('border-blue-600', 'bg-blue-50/40');
            } else {
                lbl.classList.remove('border-blue-600', 'bg-blue-50/40');
                lbl.classList.add('border-slate-200');
            }
        });
    });
});

// Toggle component visual feedback
document.querySelectorAll('.toggle-input').forEach(input => {
    input.addEventListener('change', () => {
        const lbl = input.closest('label');
        if (input.checked) {
            lbl.classList.remove('bg-slate-50', 'border-slate-200');
            lbl.classList.add('bg-emerald-50/40', 'border-emerald-200');
        } else {
            lbl.classList.add('bg-slate-50', 'border-slate-200');
            lbl.classList.remove('bg-emerald-50/40', 'border-emerald-200');
        }
    });
});
</script>

